// Preparar datos del email
const d = $input.first().json;

const company   = d.company_name  || d.company_id || 'Sin empresa';
const colab     = d.colaborador   || 'Colaborador';
const consulta  = d.consulta      || 'Solicitud de atención';
const area      = d.area          ? `\nÁrea: ${d.area}` : '';
const branch    = d.branch        ? `\nSucursal: ${d.branch}` : '';
const canal     = d.channel === 'whatsapp' ? 'WhatsApp' : 'Web';
const convId    = d.conversation_id || '';
const panelUrl  = 'https://chatbot-rrhh-528225147242.southamerica-east1.run.app/rrhh';

const subject = `[${company}] Nueva consulta de ${colab}`;

const textBody = [
  `Nueva conversación iniciada en el ChatBot RRHH.`,
  ``,
  `Empresa:     ${company}`,
  `Colaborador: ${colab}`,
  `Canal:       ${canal}`,
  area,
  branch,
  ``,
  `Consulta:`,
  consulta,
  ``,
  `Ver en el panel: ${panelUrl}`,
].filter(l => l !== undefined).join('\n');

const htmlBody = `
<div style="font-family:sans-serif; font-size:14px; color:#222;">
  <p style="margin:0 0 16px 0;">Nueva conversación iniciada en el ChatBot RRHH.</p>
  <table style="border-collapse:collapse; margin-bottom:16px;">
    <tr><td style="padding:4px 12px 4px 0; font-weight:600;">Empresa</td><td>${company}</td></tr>
    <tr><td style="padding:4px 12px 4px 0; font-weight:600;">Colaborador</td><td>${colab}</td></tr>
    <tr><td style="padding:4px 12px 4px 0; font-weight:600;">Canal</td><td>${canal}</td></tr>
    ${d.area   ? `<tr><td style="padding:4px 12px 4px 0; font-weight:600;">Área</td><td>${d.area}</td></tr>` : ''}
    ${d.branch ? `<tr><td style="padding:4px 12px 4px 0; font-weight:600;">Sucursal</td><td>${d.branch}</td></tr>` : ''}
  </table>
  <p style="margin:0 0 8px 0; font-weight:600;">Consulta:</p>
  <p style="margin:0 0 16px 0; background:#f5f5f5; padding:10px 14px; border-radius:6px;">${consulta.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</p>
  <p style="margin:0;"><a href="${panelUrl}" style="background:#2563eb; color:#fff; padding:10px 20px; border-radius:6px; text-decoration:none; display:inline-block;">Ver en el panel</a></p>
</div>`;

return [{
  json: {
    to: d.notify_email,
    subject,
    textBody,
    htmlBody,
  }
}];
